//! `FinalityCertificateV1` (G2 group C, RATIFIED 2026-10-19): wire encoding,
//! strict decoding, and verification of every reconstructed PRECOMMIT under
//! E1.
//!
//! The known-answer tests reproduce the byte-review draft's certificate
//! vectors (`docs/proposals/g2-byte-review/vectors.json`, generated by the
//! stdlib-only reference `generate.py`, not by this crate) byte for byte.
//! Both required CI jobs (x86_64 and aarch64) run these tests. Every key is a
//! test-only key from a seed `[i; 32]`; nothing here is a real validator's.

use ed25519_dalek::{Signer, SigningKey};
use serde_json::Value;
use sumchain_finality_foundations::certificate::{
    certificate_len, check_signers, decode_and_verify_certificate, quorum, verify_certificate,
    CertificateDecodeError, CertificateEncodeError, CertificateEntry, CertificateError,
    CertificateVerifyError, FinalityCertificateV1, SignerSetError, ValidatorSetResolver,
    CERT_ENTRY_LEN, CERT_HEADER_LEN, CERT_MAGIC, CERT_SCHEMA, MAX_CERT_LEN, MAX_VALIDATORS,
};
use sumchain_finality_foundations::encoding::{Round, MAX_ROUND};
use sumchain_finality_foundations::vote::{
    AuthenticatedValidatorSet, FinalityVoteV1, VoteContext, VoteType, NIL_BLOCK_ID, VOTE_MAGIC,
};
use sumchain_finality_foundations::Digest;

const DRAFT_VECTORS: &str = include_str!("../../../docs/proposals/g2-byte-review/vectors.json");

fn draft(name: &str) -> Vec<u8> {
    let v: Value = serde_json::from_str(DRAFT_VECTORS).expect("the draft vectors are JSON");
    let hex = v["vectors"]
        .as_array()
        .expect("a vector list")
        .iter()
        .find(|x| x["name"] == name)
        .unwrap_or_else(|| panic!("draft vector {name:?}"))["hex"]
        .as_str()
        .expect("a hex string")
        .to_owned();
    hex::decode(hex).expect("valid hex")
}

fn digest(bytes: &[u8]) -> Digest {
    bytes.try_into().expect("32 bytes")
}

fn seed_key(index: u16) -> SigningKey {
    SigningKey::from_bytes(&[u8::try_from(index + 1).expect("small test set"); 32])
}

/// A synthetic commitment for a set of `n` (computing the real one is not
/// ratified; the verifier only compares it).
fn valset_commitment(n: u16) -> Digest {
    let mut d = [0x5au8; 32];
    d[..2].copy_from_slice(&n.to_le_bytes());
    d
}

const CONFIG: Digest = [0xc0; 32];
const BLOCK: Digest = [0xb1; 32];
const HEIGHT: u64 = 7;

struct Ctx {
    height: u64,
    commitment: Digest,
    set: AuthenticatedValidatorSet,
}

impl Ctx {
    fn new(n: u16) -> Ctx {
        Ctx::with(HEIGHT, CONFIG, valset_commitment(n), n)
    }
    fn with(height: u64, commitment: Digest, valset: Digest, n: u16) -> Ctx {
        let keys: Vec<[u8; 32]> = (0..n)
            .map(|i| seed_key(i).verifying_key().to_bytes())
            .collect();
        Ctx {
            height,
            commitment,
            set: AuthenticatedValidatorSet::new(valset, &keys).expect("a valid synthetic set"),
        }
    }
}

impl VoteContext for Ctx {
    fn consensus_config_commitment(&self, height: u64) -> Option<Digest> {
        (height == self.height).then_some(self.commitment)
    }
    fn validator_set(&self, height: u64) -> Option<&AuthenticatedValidatorSet> {
        (height == self.height).then_some(&self.set)
    }
}

fn precommit(n: u16, round: Round, index: u16) -> FinalityVoteV1 {
    FinalityVoteV1 {
        consensus_config_commitment: CONFIG,
        height: HEIGHT,
        block_id: BLOCK,
        round,
        vote_type: VoteType::Precommit,
        validator_set_commitment: valset_commitment(n),
        validator_index: index,
    }
}

fn cert_with_round(n: u16, signers: &[u16], round: Round) -> FinalityCertificateV1 {
    FinalityCertificateV1 {
        consensus_config_commitment: CONFIG,
        height: HEIGHT,
        block_id: BLOCK,
        round,
        validator_set_commitment: valset_commitment(n),
        entries: signers
            .iter()
            .map(|&i| CertificateEntry {
                validator_index: i,
                signature: seed_key(i)
                    .sign(&precommit(n, round, i).preimage())
                    .to_bytes(),
            })
            .collect(),
    }
}

fn cert(n: u16, signers: &[u16]) -> FinalityCertificateV1 {
    cert_with_round(n, signers, Round::ZERO)
}

fn bytes_of(c: &FinalityCertificateV1) -> Vec<u8> {
    c.encode().expect("a well-formed certificate encodes")
}

fn verify_bytes(bytes: &[u8], ctx: &Ctx) -> Result<(), CertificateError> {
    decode_and_verify_certificate(bytes, HEIGHT, &BLOCK, ctx).map(|_| ())
}

fn verify_err(c: &FinalityCertificateV1, ctx: &Ctx) -> CertificateVerifyError {
    verify_certificate(c, HEIGHT, &BLOCK, ctx).expect_err("refused")
}

// ---------------------------------------------------------------------------
// Known answers (byte-review draft vectors)
// ---------------------------------------------------------------------------

fn kat(n: u16, signers: &[u16], vector: &str, valset_vector: &str) {
    let want = draft(vector);
    let commitment = digest(&draft("synthetic config commitment"));
    let valset = digest(&draft(valset_vector));
    let block = digest(&draft("finalized pointer h=7")[8..40]);
    for i in 0..n {
        assert_eq!(
            seed_key(i).verifying_key().to_bytes().as_slice(),
            draft(&format!("pubkey[{i}]")).as_slice(),
            "seed key {i} is the draft's test key"
        );
    }
    let entries = signers
        .iter()
        .map(|&i| {
            let vote = FinalityVoteV1 {
                consensus_config_commitment: commitment,
                height: 7,
                block_id: block,
                round: Round::ZERO,
                vote_type: VoteType::Precommit,
                validator_set_commitment: valset,
                validator_index: i,
            };
            CertificateEntry {
                validator_index: i,
                signature: seed_key(i).sign(&vote.preimage()).to_bytes(),
            }
        })
        .collect();
    let built = FinalityCertificateV1 {
        consensus_config_commitment: commitment,
        height: 7,
        block_id: block,
        round: Round::ZERO,
        validator_set_commitment: valset,
        entries,
    };
    let encoded = built.encode().unwrap();
    assert_eq!(
        hex::encode(&encoded),
        hex::encode(&want),
        "{vector}: byte for byte"
    );
    assert_eq!(encoded.len(), certificate_len(signers.len() as u16));
    let decoded = FinalityCertificateV1::decode(&want).unwrap();
    assert_eq!(decoded, built);
    let ctx = Ctx::with(7, commitment, valset, n);
    let verified = decode_and_verify_certificate(&want, 7, &block, &ctx).unwrap();
    assert_eq!(verified.signers().indices(), signers);
    assert_eq!(verified.signers().validator_count(), n);
}

#[test]
fn kat_reproduces_the_draft_certificate_n4_signers_0_1_3() {
    kat(
        4,
        &[0, 1, 3],
        "certificate n=4 h=7 r=0 signers {0,1,3}",
        "valset n=4 commitment",
    );
}

#[test]
fn kat_reproduces_the_draft_certificate_n2_signers_0_1() {
    kat(
        2,
        &[0, 1],
        "certificate n=2 h=7 r=0 signers {0,1}",
        "valset n=2 commitment",
    );
}

#[test]
fn kat_entry_signature_is_the_ratified_vote_vector_signature() {
    // Entry 1 of the n = 4 certificate is validator 1's PRECOMMIT, the same
    // signature as the ratified vote vector.
    let c =
        FinalityCertificateV1::decode(&draft("certificate n=4 h=7 r=0 signers {0,1,3}")).unwrap();
    assert_eq!(c.entries[1].validator_index, 1);
    assert_eq!(
        c.entries[1].signature.as_slice(),
        draft("vote precommit h=7 r=0 idx=1 signature").as_slice()
    );
    assert_eq!(
        c.precommit(1).preimage().as_slice(),
        draft("vote precommit h=7 r=0 idx=1 preimage").as_slice()
    );
}

#[test]
fn layout_constants() {
    // "FCRTv1" ‖ NUL, spelled independently of the constant.
    assert_eq!(CERT_MAGIC, [0x46, 0x43, 0x52, 0x54, 0x76, 0x31, 0x00]);
    assert_eq!(CERT_SCHEMA, 1);
    assert_eq!(CERT_HEADER_LEN, 7 + 2 + 32 + 8 + 32 + 4 + 32 + 2);
    assert_eq!(CERT_ENTRY_LEN, 66);
    let c = cert(4, &[0, 1, 3]);
    let b = bytes_of(&c);
    assert_eq!(&b[0..7], &CERT_MAGIC);
    assert_eq!(&b[7..9], &1u16.to_le_bytes());
    assert_eq!(&b[9..41], &CONFIG);
    assert_eq!(&b[41..49], &HEIGHT.to_le_bytes());
    assert_eq!(&b[49..81], &BLOCK);
    assert_eq!(&b[81..85], &0u32.to_le_bytes());
    assert_eq!(&b[85..117], &valset_commitment(4));
    assert_eq!(&b[117..119], &3u16.to_le_bytes());
    assert_eq!(&b[119..121], &0u16.to_le_bytes());
    assert_eq!(&b[185..187], &1u16.to_le_bytes());
    assert_eq!(&b[251..253], &3u16.to_le_bytes());
}

#[test]
fn round_trip_is_exact() {
    for (n, signers) in [
        (1, vec![0]),
        (2, vec![0, 1]),
        (4, vec![0, 2, 3]),
        (7, vec![0, 1, 2, 4, 6]),
    ] {
        let b = bytes_of(&cert(n, &signers));
        let d = FinalityCertificateV1::decode(&b).unwrap();
        assert_eq!(d.encode().unwrap(), b);
    }
}

// ---------------------------------------------------------------------------
// Sizes: labelled by k (the quorum minimum and the all-signers size differ)
// ---------------------------------------------------------------------------

#[test]
fn sizes_by_k_minimum_quorum_and_all_signers() {
    // (n, q(n), size at k = q(n), size at k = n)
    let table: [(u16, u16, usize, usize); 7] = [
        (1, 1, 185, 185),
        (2, 2, 251, 251),
        (3, 3, 317, 317),
        (4, 3, 317, 383),
        (7, 5, 449, 581),
        (100, 67, 4_541, 6_719),
        (65_535, 43_691, 2_883_725, 4_325_429),
    ];
    for (n, q, at_quorum, all) in table {
        assert_eq!(quorum(n), q, "q({n})");
        assert_eq!(
            certificate_len(q),
            at_quorum,
            "n = {n}, minimum quorum k = {q}"
        );
        assert_eq!(certificate_len(n), all, "n = {n}, all signers k = {n}");
    }
    assert_eq!(MAX_CERT_LEN, 4_325_429);
    assert_eq!(MAX_CERT_LEN, certificate_len(MAX_VALIDATORS));
    assert_eq!(bytes_of(&cert(4, &[0, 1, 2])).len(), 317);
    assert_eq!(bytes_of(&cert(4, &[0, 1, 2, 3])).len(), 383);
}

// ---------------------------------------------------------------------------
// Boundaries on k and n
// ---------------------------------------------------------------------------

#[test]
fn k_boundaries_for_small_sets() {
    for n in [1u16, 2, 3, 4, 7] {
        let ctx = Ctx::new(n);
        let q = quorum(n);
        // k = q(n) - 1: below quorum.
        let below: Vec<u16> = (0..q - 1).collect();
        assert_eq!(
            verify_err(&cert(n, &below), &ctx),
            CertificateVerifyError::Signers(SignerSetError::BelowQuorum {
                k: usize::from(q - 1),
                quorum: q,
                n
            }),
            "n = {n}, k = q - 1"
        );
        // k = q(n) and k = n: accepted.
        let at_quorum: Vec<u16> = (0..q).collect();
        verify_certificate(&cert(n, &at_quorum), HEIGHT, &BLOCK, &ctx).expect("k = q(n)");
        let all: Vec<u16> = (0..n).collect();
        verify_certificate(&cert(n, &all), HEIGHT, &BLOCK, &ctx).expect("k = n");
        // k = n + 1: ascending distinct indices must include one ≥ n.
        let over: Vec<u16> = (0..=n).collect();
        assert_eq!(
            verify_err(&cert(n, &over), &ctx),
            CertificateVerifyError::Signers(SignerSetError::AboveSetSize {
                k: usize::from(n) + 1,
                n
            }),
            "n = {n}, k = n + 1"
        );
    }
}

struct FixedCount(Digest, u16);

impl ValidatorSetResolver for FixedCount {
    fn validator_count(&self, commitment: &Digest) -> Option<u16> {
        (commitment == &self.0).then_some(self.1)
    }
}

#[test]
fn count_boundaries_at_the_65535_cap_without_signatures() {
    let c = valset_commitment(MAX_VALIDATORS);
    let r = FixedCount(c, MAX_VALIDATORS);
    let q = quorum(MAX_VALIDATORS);
    assert_eq!(q, 43_691);
    let below: Vec<u16> = (0..q - 1).collect();
    assert_eq!(
        check_signers(&c, &below, &r),
        Err(SignerSetError::BelowQuorum {
            k: usize::from(q) - 1,
            quorum: q,
            n: MAX_VALIDATORS
        })
    );
    let at: Vec<u16> = (0..q).collect();
    assert!(check_signers(&c, &at, &r).is_ok());
    let all: Vec<u16> = (0..MAX_VALIDATORS).collect();
    assert_eq!(check_signers(&c, &all, &r).unwrap().indices().len(), 65_535);
}

/// A structurally valid certificate of `k` entries with zero signatures.
fn unsigned_bytes(k: u16, valset: Digest) -> Vec<u8> {
    let mut b = Vec::with_capacity(certificate_len(k));
    b.extend_from_slice(&CERT_MAGIC);
    b.extend_from_slice(&1u16.to_le_bytes());
    b.extend_from_slice(&CONFIG);
    b.extend_from_slice(&HEIGHT.to_le_bytes());
    b.extend_from_slice(&BLOCK);
    b.extend_from_slice(&0u32.to_le_bytes());
    b.extend_from_slice(&valset);
    b.extend_from_slice(&k.to_le_bytes());
    for i in 0..k {
        b.extend_from_slice(&i.to_le_bytes());
        b.extend_from_slice(&[0u8; 64]);
    }
    b
}

#[test]
fn a_full_size_certificate_decodes_and_counts_are_refused_before_any_signature() {
    let b = unsigned_bytes(MAX_VALIDATORS, valset_commitment(4));
    assert_eq!(b.len(), MAX_CERT_LEN);
    let c = FinalityCertificateV1::decode(&b).expect("structurally valid at the cap");
    assert_eq!(c.signer_count(), 65_535);
    // Against a set of 4 the count is refused before any signature is
    // checked: the all-zero signatures would otherwise fail E1.
    let ctx = Ctx::new(4);
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signers(SignerSetError::AboveSetSize { k: 65_535, n: 4 })
    );
}

// ---------------------------------------------------------------------------
// Malformed inputs (decode)
// ---------------------------------------------------------------------------

fn valid() -> Vec<u8> {
    bytes_of(&cert(4, &[0, 1, 3]))
}

#[test]
fn every_truncation_is_refused() {
    let b = valid();
    for len in 0..b.len() {
        let err = FinalityCertificateV1::decode(&b[..len]).expect_err("truncated");
        if len < CERT_HEADER_LEN {
            assert_eq!(err, CertificateDecodeError::ShortHeader { actual: len });
        } else {
            assert_eq!(
                err,
                CertificateDecodeError::Length {
                    k: 3,
                    expected: 317,
                    actual: len
                }
            );
        }
    }
}

#[test]
fn trailing_bytes_are_refused() {
    let mut b = valid();
    for extra in [1usize, 2, 65, 66, 67] {
        let mut t = b.clone();
        t.extend(std::iter::repeat_n(0u8, extra));
        assert_eq!(
            FinalityCertificateV1::decode(&t),
            Err(CertificateDecodeError::Length {
                k: 3,
                expected: 317,
                actual: 317 + extra
            })
        );
    }
    // A whole extra entry with k unchanged is trailing too.
    b.extend_from_slice(&[0u8; 66]);
    assert!(matches!(
        FinalityCertificateV1::decode(&b),
        Err(CertificateDecodeError::Length { k: 3, .. })
    ));
}

#[test]
fn k_that_disagrees_with_the_length_is_refused() {
    let b = valid();
    for k in [0u16, 2, 4, 5, u16::MAX] {
        let mut t = b.clone();
        t[117..119].copy_from_slice(&k.to_le_bytes());
        assert_eq!(
            FinalityCertificateV1::decode(&t),
            Err(CertificateDecodeError::Length {
                k,
                expected: certificate_len(k),
                actual: 317
            })
        );
    }
}

#[test]
fn wrong_magic_and_schema_are_refused() {
    let b = valid();
    for i in 0..7 {
        let mut t = b.clone();
        t[i] ^= 0x01;
        assert_eq!(
            FinalityCertificateV1::decode(&t),
            Err(CertificateDecodeError::Magic),
            "byte {i}"
        );
    }
    let mut vote_magic = b.clone();
    vote_magic[..7].copy_from_slice(&VOTE_MAGIC);
    assert_eq!(
        FinalityCertificateV1::decode(&vote_magic),
        Err(CertificateDecodeError::Magic)
    );
    for schema in [0u16, 2, u16::MAX] {
        let mut t = b.clone();
        t[7..9].copy_from_slice(&schema.to_le_bytes());
        assert_eq!(
            FinalityCertificateV1::decode(&t),
            Err(CertificateDecodeError::Schema(schema))
        );
    }
}

#[test]
fn round_at_the_cap_is_accepted_and_above_it_refused() {
    let at_cap = cert_with_round(4, &[0, 1, 2], Round::MAX);
    let b = bytes_of(&at_cap);
    assert_eq!(&b[81..85], &MAX_ROUND.to_le_bytes());
    verify_bytes(&b, &Ctx::new(4)).expect("round 2^20 is valid");
    let mut over = b.clone();
    over[81..85].copy_from_slice(&(MAX_ROUND + 1).to_le_bytes());
    assert!(matches!(
        FinalityCertificateV1::decode(&over),
        Err(CertificateDecodeError::Round(_))
    ));
    let mut max = b;
    max[81..85].copy_from_slice(&u32::MAX.to_le_bytes());
    assert!(matches!(
        FinalityCertificateV1::decode(&max),
        Err(CertificateDecodeError::Round(_))
    ));
}

#[test]
fn nil_block_is_refused_everywhere() {
    let mut b = valid();
    b[49..81].copy_from_slice(&NIL_BLOCK_ID);
    assert_eq!(
        FinalityCertificateV1::decode(&b),
        Err(CertificateDecodeError::NilBlock)
    );
    let mut c = cert(4, &[0, 1, 2]);
    c.block_id = NIL_BLOCK_ID;
    assert_eq!(c.encode(), Err(CertificateEncodeError::NilBlock));
    // A constructed (never decoded) nil certificate is refused by the
    // verifier as well, even when the caller asks to commit nil.
    let ctx = Ctx::new(4);
    assert_eq!(
        verify_certificate(&c, HEIGHT, &NIL_BLOCK_ID, &ctx),
        Err(CertificateVerifyError::NilBlock)
    );
}

#[test]
fn descending_and_duplicate_indices_are_refused() {
    let base = cert(4, &[0, 1, 3]);
    let b = bytes_of(&base);
    let index_at = |j: usize| CERT_HEADER_LEN + CERT_ENTRY_LEN * j;
    // (entry, new index, the violation the scan meets first)
    for (j, value, previous, index) in [
        (1usize, 0u16, 0u16, 0u16), // duplicate of entry 0
        (2, 1, 1, 1),               // duplicate of entry 1
        (2, 0, 1, 0),               // descending
        (1, 3, 3, 3),               // entry 1 = entry 2
        (0, 2, 2, 1),               // entry 0 above entry 1
    ] {
        let mut t = b.clone();
        t[index_at(j)..index_at(j) + 2].copy_from_slice(&value.to_le_bytes());
        assert_eq!(
            FinalityCertificateV1::decode(&t),
            Err(CertificateDecodeError::NotStrictlyAscending { previous, index }),
            "entry {j} set to {value}"
        );
    }
    let mut dup = base.clone();
    dup.entries[1].validator_index = 0;
    assert_eq!(
        dup.encode(),
        Err(CertificateEncodeError::NotStrictlyAscending {
            previous: 0,
            index: 0
        })
    );
    let mut desc = base;
    desc.entries.swap(0, 2);
    assert_eq!(
        desc.encode(),
        Err(CertificateEncodeError::NotStrictlyAscending {
            previous: 3,
            index: 1
        })
    );
}

#[test]
fn every_single_byte_flip_is_refused() {
    let b = valid();
    let ctx = Ctx::new(4);
    verify_bytes(&b, &ctx).expect("the unmodified certificate verifies");
    for i in 0..b.len() {
        for bit in [0x01u8, 0x80] {
            let mut t = b.clone();
            t[i] ^= bit;
            assert!(
                verify_bytes(&t, &ctx).is_err(),
                "flip {bit:#04x} at offset {i} accepted"
            );
        }
    }
}

// ---------------------------------------------------------------------------
// Verification (context and signatures)
// ---------------------------------------------------------------------------

#[test]
fn an_out_of_range_index_is_refused() {
    let ctx = Ctx::new(4);
    let mut c = cert(4, &[0, 1, 3]);
    c.entries[2].validator_index = 4;
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signers(SignerSetError::IndexOutOfRange { index: 4, n: 4 })
    );
}

#[test]
fn one_bad_signature_refuses_the_whole_certificate() {
    let ctx = Ctx::new(4);
    for (bad, index) in [(0usize, 0u16), (1, 1), (3, 3)] {
        // k = 4 ≥ q(4) = 3: dropping the bad entry would still leave a
        // quorum, but nothing is trimmed.
        let mut c = cert(4, &[0, 1, 2, 3]);
        c.entries[bad].signature[10] ^= 0x01;
        assert_eq!(
            verify_err(&c, &ctx),
            CertificateVerifyError::Signature { index }
        );
    }
}

#[test]
fn a_signature_from_a_non_member_key_is_refused() {
    let ctx = Ctx::new(4);
    let mut c = cert(4, &[0, 1, 2]);
    let stranger = SigningKey::from_bytes(&[0xee; 32]);
    c.entries[1].signature = stranger.sign(&c.precommit(1).preimage()).to_bytes();
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signature { index: 1 }
    );
    // Another member's valid PRECOMMIT under the wrong index is refused too.
    let mut swapped = cert(4, &[0, 1, 2]);
    swapped.entries[1].signature = seed_key(2)
        .sign(&swapped.precommit(1).preimage())
        .to_bytes();
    assert_eq!(
        verify_err(&swapped, &ctx),
        CertificateVerifyError::Signature { index: 1 }
    );
}

#[test]
fn a_prevote_signature_is_not_a_precommit() {
    let ctx = Ctx::new(4);
    let mut c = cert(4, &[0, 1, 2]);
    let mut prevote = c.precommit(2);
    prevote.vote_type = VoteType::Prevote;
    c.entries[2].signature = seed_key(2).sign(&prevote.preimage()).to_bytes();
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signature { index: 2 }
    );
}

#[test]
fn a_signature_for_another_round_is_refused() {
    let ctx = Ctx::new(4);
    let mut c = cert(4, &[0, 1, 2]);
    let other = precommit(4, Round::new(1).unwrap(), 0);
    c.entries[0].signature = seed_key(0).sign(&other.preimage()).to_bytes();
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signature { index: 0 }
    );
}

#[test]
fn a_malleated_signature_is_refused_under_e1() {
    // S + ℓ is the textbook malleation; E1 refuses a non-canonical S.
    const L: [u8; 32] = [
        0xed, 0xd3, 0xf5, 0x5c, 0x1a, 0x63, 0x12, 0x58, 0xd6, 0x9c, 0xf7, 0xa2, 0xde, 0xf9, 0xde,
        0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x10,
    ];
    let ctx = Ctx::new(4);
    let mut c = cert(4, &[0, 1, 2]);
    let sig = &mut c.entries[1].signature;
    let mut carry = 0u16;
    for i in 0..32 {
        let s = u16::from(sig[32 + i]) + u16::from(L[i]) + carry;
        sig[32 + i] = s as u8;
        carry = s >> 8;
    }
    assert_eq!(carry, 0, "S + ℓ fits 32 bytes for this signature");
    assert_eq!(
        verify_err(&c, &ctx),
        CertificateVerifyError::Signature { index: 1 }
    );
}

#[test]
fn wrong_height_block_or_commitments_are_refused() {
    let ctx = Ctx::new(4);
    let c = cert(4, &[0, 1, 2]);
    assert_eq!(
        verify_certificate(&c, HEIGHT + 1, &BLOCK, &ctx),
        Err(CertificateVerifyError::HeightMismatch {
            named: HEIGHT,
            committed: HEIGHT + 1
        })
    );
    assert_eq!(
        verify_certificate(&c, HEIGHT, &[0xb2; 32], &ctx),
        Err(CertificateVerifyError::BlockMismatch)
    );
    let other_config = Ctx::with(HEIGHT, [0xc1; 32], valset_commitment(4), 4);
    assert_eq!(
        verify_err(&c, &other_config),
        CertificateVerifyError::ConfigCommitmentMismatch
    );
    let other_set = Ctx::with(HEIGHT, CONFIG, [0x77; 32], 4);
    assert_eq!(
        verify_err(&c, &other_set),
        CertificateVerifyError::ValidatorSetCommitmentMismatch
    );
    let other_height = Ctx::with(HEIGHT + 1, CONFIG, valset_commitment(4), 4);
    assert_eq!(
        verify_err(&c, &other_height),
        CertificateVerifyError::NoConfigCommitment { height: HEIGHT }
    );
}

struct ConfigOnly;

impl VoteContext for ConfigOnly {
    fn consensus_config_commitment(&self, _height: u64) -> Option<Digest> {
        Some(CONFIG)
    }
    fn validator_set(&self, _height: u64) -> Option<&AuthenticatedValidatorSet> {
        None
    }
}

#[test]
fn an_unauthenticated_set_is_refused() {
    let c = cert(4, &[0, 1, 2]);
    assert_eq!(
        verify_certificate(&c, HEIGHT, &BLOCK, &ConfigOnly),
        Err(CertificateVerifyError::NoValidatorSet { height: HEIGHT })
    );
}

#[test]
fn a_certificate_signed_for_a_smaller_set_is_not_valid_for_a_larger_one() {
    // The same three signatures, presented against a set of 7 under the
    // set-of-7 commitment: the commitment in each preimage differs, and
    // three signers are below q(7) = 5 anyway.
    let ctx7 = Ctx::new(7);
    let c4 = cert(4, &[0, 1, 2]);
    let mut moved = c4.clone();
    moved.validator_set_commitment = valset_commitment(7);
    assert!(matches!(
        verify_err(&moved, &ctx7),
        CertificateVerifyError::Signers(SignerSetError::BelowQuorum {
            k: 3,
            quorum: 5,
            n: 7
        })
    ));
    let mut padded = cert(7, &[0, 1, 2, 3, 4]);
    for j in 0..3 {
        padded.entries[j].signature = c4.entries[j].signature;
    }
    assert_eq!(
        verify_err(&padded, &ctx7),
        CertificateVerifyError::Signature { index: 0 }
    );
}

#[test]
fn encode_refuses_more_than_65535_entries() {
    let mut c = cert(1, &[0]);
    c.entries = vec![c.entries[0]; usize::from(MAX_VALIDATORS) + 1];
    assert_eq!(
        c.encode(),
        Err(CertificateEncodeError::TooManyEntries { k: 65_536 })
    );
}
